class Solution {
    vector<int> recover(vector<int> sums,int n){
        if(n==0)return {};
        sort(sums.begin(),sums.end());
        int delta=sums[1]-sums[0];
        unordered_map<int,int>freq;
        for(int x:sums)++freq[x];
        vector<int>a,b;
        for(int x:sums){
            if(freq[x]==0)continue;
            --freq[x];--freq[x+delta];a.push_back(x);b.push_back(x+delta);
        }
        if(find(a.begin(),a.end(),0)!=a.end()){
            auto res=recover(a,n-1);res.push_back(delta);return res;
        }
        auto res=recover(b,n-1);res.push_back(-delta);return res;
    }
public:
    vector<int> recoverArray(int n,vector<int>& sums){return recover(sums,n);}
};
